public final class DataComponentMap {
 private final Map<DataComponentType<?>,Object> values;
 public DataComponentMap(Map<DataComponentType<?>,Object> input){values=new LinkedHashMap<>(input);}
 public boolean has(DataComponentType<?> type){return values.containsKey(type);}
 @SuppressWarnings("unchecked") public <T>T get(DataComponentType<T> type){return (T)values.get(type);}
 @SuppressWarnings({"unchecked","rawtypes"}) public Stream<TypedDataComponent<?>> stream(){return values.entrySet().stream().map(e->new TypedDataComponent((DataComponentType)e.getKey(),e.getValue()));}
 public Map<DataComponentType<?>,Object> copyValues(){return new LinkedHashMap<>(values);}
 @Override public boolean equals(Object object){return object instanceof DataComponentMap map && values.equals(map.values);}
 @Override public int hashCode(){return values.hashCode();}
