package net.minecraft.world.item;
import java.util.*; import net.minecraft.core.component.*;
/** Modeled host. Components and item identity, not count, define strict equality. */
public final class ItemStack {
 public static final DataComponentType<Integer> MAX_STACK_SIZE=new DataComponentType<>("minecraft:max_stack_size");
 public static final DataComponentType<String> RARITY=new DataComponentType<>("minecraft:rarity");
 public static final Item AIR=new Item("minecraft:air");
 public static final ItemStack EMPTY=new ItemStack(AIR,0);
 private final Item item; private final int count; private final DataComponentMap components;
 public ItemStack(Item item,int count){this(item,count,defaults());}
 public ItemStack(Item item,int count,DataComponentMap components){this.item=item;this.count=count;this.components=components;}
 private static DataComponentMap defaults(){var values=new LinkedHashMap<DataComponentType<?>,Object>();values.put(MAX_STACK_SIZE,64);values.put(RARITY,"common");return new DataComponentMap(values);}
 public Item getItem(){return item;} public int getCount(){return count;} public DataComponentMap getComponents(){return components;}
 public <T>ItemStack with(DataComponentType<T> key,T value){var values=components.copyValues();if(value==null)values.remove(key);else values.put(key,value);return new ItemStack(item,count,new DataComponentMap(values));}
 public ItemStack copyWithCount(int value){return new ItemStack(item,value,new DataComponentMap(components.copyValues()));}
 public static boolean isSameItemSameComponents(ItemStack a,ItemStack b){return a.item==b.item && a.components.equals(b.components);}
}

