package dev.ftb.mods.ftblibrary.config;
import java.util.*;import java.util.function.Function;
/** Modeled fluent public surface; NAME_MAP fallback behavior is pinned independently. */
public final class NameMap<T> {
 private final T fallback;private final Map<String,T> values;
 private NameMap(T fallback,Map<String,T> values){this.fallback=fallback;this.values=values;}
 public T get(String name){return values.getOrDefault(name,fallback);}
 public String getName(T value){return values.entrySet().stream().filter(e->e.getValue()==value).findFirst().orElseThrow().getKey();}
 public static <T>Builder<T> of(T fallback,T[] values){return new Builder<>(fallback,values);}
 public static final class Builder<T>{private final T fallback;private final T[] values;private Function<T,String> id;
  Builder(T fallback,T[] values){this.fallback=fallback;this.values=values;} public Builder<T> id(Function<T,String> function){id=function;return this;}
  public NameMap<T> create(){var mapped=new LinkedHashMap<String,T>();for(T value:values)mapped.put(id.apply(value),value);return new NameMap<>(fallback,mapped);}
 }
}

